def set_language(lang: str):
    global _current_lang
    _current_lang = lang


def get_language() -> str:
    return _current_lang


def t(key: str, lang: str = None) -> str:
    """Translate a key to the current (or specified) language."""
    use_lang = lang or _current_lang
    entry = TRANSLATIONS.get(key)
    if entry is None:
        return key  # fallback: return key itself
    return entry.get(use_lang) or entry.get("English") or key


def load_from_settings():
    """Read app_language from settings.json and apply it."""
    try:
        import settings as s
        lang = s.get("language", "app_language", "English")
        set_language(lang)
    except Exception:
        pass
